1: // Assistant chat panel.
2: //
3: // Honest about three things:
4: //   1. The text shown is exactly what the backend returned; we do not
5: //      simulate streaming, do not invent partial answers, and do not claim
6: //      a model is "thinking" when one isn't.
7: //   2. Remote providers only run if the operator ticks the explicit consent
8: //      checkbox. The state machine below refuses to send until consent is on.
9: //   3. For the local helper, model is optional (the backend ignores it).
10: //      For API routes, model is required.
11: 
12: import { useEffect, useRef, useState } from 'react';
13: import {
14:   postChat,
15:   StudioAbortError,
16:   StudioApiError,
17:   StudioAuthError,
18:   StudioNetworkError,
19: } from '../../api/client';
20: import { useUiState, dispatch } from '../../state/store';
21: import type { ChatRequest } from '../../types/studio';
22: import type { ReactElement } from 'react';
23: 
24: const REMOTE_PROVIDERS: ReadonlySet<string> = new Set(['openai', 'openrouter', 'codex']);
25: 
26: export function ChatPanel(): ReactElement {
27:   const connection = useUiState((s) => s.connection);
28:   const server = useUiState((s) => s.server);
29:   const chat = useUiState((s) => s.chat);
30:   const [providerId, setProviderId] = useState<string>('');
31:   const [model, setModel] = useState<string>('');
32:   const [prompt, setPrompt] = useState<string>('');
33:   const [allowRemote, setAllowRemote] = useState<boolean>(false);
34:   const controllerRef = useRef<AbortController | null>(null);
35: 
36:   useEffect(() => {
37:     if (!providerId && server.providers[0]) {
38:       setProviderId(server.providers[0].id);
39:     }
40:   }, [server.providers, providerId]);
41: 
42:   useEffect(() => () => {
43:     if (controllerRef.current) {
44:       controllerRef.current.abort();
45:       controllerRef.current = null;
46:     }
47:   }, []);
48: 
49:   const provider = server.providers.find((p) => p.id === providerId);
50:   const configured = provider?.configured === true;
51:   const isLocal = providerId === 'local' || providerId === 'local-helper';
52:   const requiresRemoteConsent = REMOTE_PROVIDERS.has(providerId);
53:   const requiresModel = !isLocal;
54: 
55:   const canSend =
56:     connection.kind === 'ready' &&
57:     !chat.inFlight &&
58:     prompt.trim().length > 0 &&
59:     providerId.length > 0 &&
60:     configured &&
61:     (!requiresRemoteConsent || allowRemote) &&
62:     (!requiresModel || model.trim().length > 0);
63: 
64:   async function onSend(): Promise<void> {
65:     if (!canSend || connection.kind !== 'ready') return;
66:     if (controllerRef.current) controllerRef.current.abort();
67:     const controller = new AbortController();
68:     controllerRef.current = controller;
69:     const trimmedPrompt = prompt.trim();
70:     const trimmedModel = model.trim();
71:     const payload: ChatRequest = {
72:       provider: providerId as ChatRequest['provider'],
73:       model: trimmedModel.length > 0 ? trimmedModel : null,
74:       prompt: trimmedPrompt,
75:       allow_remote: allowRemote,
76:     };
77:     setPrompt('');
78:     dispatch({
79:       type: 'chat/send',
80:       request: {
81:         provider: payload.provider,
82:         model: payload.model,
83:         prompt: payload.prompt,
84:         allowRemote: payload.allow_remote,
85:       },
86:     });
87:     try {
88:       const response = await postChat(connection.connection, payload, controller.signal);
89:       if (!controller.signal.aborted) {
90:         dispatch({
91:           type: 'chat/response',
92:           response: { text: response.text, provider: response.provider, model: response.model },
93:         });
94:       }
95:     } catch (cause) {
96:       if (controller.signal.aborted) {
97:         // Operator cancelled: clear the in-flight state without an error.
98:         dispatch({ type: 'chat/error', message: 'Cancelled', kind: 'cancelled' });
99:         return;
100:       }
101:       const desc = describeError(cause);
102:       dispatch({ type: 'chat/error', message: desc.message, kind: desc.kind });
103:     } finally {
104:       if (controllerRef.current === controller) controllerRef.current = null;
105:     }
106:   }
107: 
108:   function onCancel(): void {
109:     if (controllerRef.current) controllerRef.current.abort();
110:   }
111: 
112:   function onClear(): void {
113:     if (controllerRef.current) controllerRef.current.abort();
114:     dispatch({ type: 'chat/clear' });
115:   }
116: 
117:   return (
118:     <section className="chat-panel" aria-label="Assistant chat">
119:       <header className="chat-panel-header">
120:         <h2>Assistant</h2>
121:         <button
122:           type="button"
123:           className="chat-panel-clear"
124:           onClick={onClear}
125:           disabled={chat.thread.length === 0}
126:         >
127:           Clear
128:         </button>
129:       </header>
130:       <div className="chat-panel-thread" role="log" aria-live="polite">
131:         {chat.thread.length === 0 ? (
132:           <p className="chat-panel-empty">
133:             Pick a configured provider, type a prompt, and send. Remote providers require the consent toggle.
134:           </p>
135:         ) : null}
136:         {chat.thread.map((entry, index) => (
137:           <article
138:             key={`${entry.role}-${entry.at}-${index}`}
139:             className={`chat-panel-message chat-panel-message-${entry.role}`}
140:           >
141:             <span className="chat-panel-message-role">{entry.role === 'user' ? 'You' : 'Assistant'}</span>
142:             <p>{entry.text}</p>
143:           </article>
144:         ))}
145:         {chat.inFlight ? <p className="chat-panel-pending">Awaiting response…</p> : null}
146:         {chat.lastError && chat.lastErrorKind !== 'cancelled' ? (
147:           <p className="chat-panel-error" role="alert">{chat.lastError}</p>
148:         ) : null}
149:         {chat.lastErrorKind === 'cancelled' ? (
150:           <p className="chat-panel-pending" role="status">Request cancelled</p>
151:         ) : null}
152:       </div>
153:       <form
154:         className="chat-panel-form"
155:         onSubmit={(event) => {
156:           event.preventDefault();
157:           void onSend();
158:         }}
159:       >
160:         <label className="chat-panel-field">
161:           <span>Provider</span>
162:           <select
163:             value={providerId}
164:             onChange={(event) => {
165:               setProviderId(event.target.value);
166:               setAllowRemote(false);
167:             }}
168:           >
169:             <option value="" disabled>Select a provider</option>
170:             {server.providers.map((provider) => (
171:               <option key={provider.id} value={provider.id} disabled={!provider.configured}>
172:                 {provider.name}{provider.configured ? '' : ' (not configured)'}
173:               </option>
174:             ))}
175:           </select>
176:         </label>
177:         <label className="chat-panel-field">
178:           <span>
179:             Model{isLocal ? ' (optional for local helper)' : ''}
180:           </span>
181:           <input
182:             type="text"
183:             value={model}
184:             onChange={(event) => setModel(event.target.value)}
185:             placeholder={isLocal ? 'optional' : 'e.g. gpt-4o-mini'}
186:           />
187:         </label>
188:         {requiresRemoteConsent ? (
189:           <label className="chat-panel-consent">
190:             <input
191:               type="checkbox"
192:               checked={allowRemote}
193:               onChange={(event) => setAllowRemote(event.target.checked)}
194:             />
195:             <span>
196:               I consent to this prompt being sent to a remote provider. Without this tick the request
197:               will not leave the loopback backend.
198:             </span>
199:           </label>
200:         ) : null}
201:         <label className="chat-panel-field chat-panel-field-grow">
202:           <span>Prompt</span>
203:           <textarea
204:             value={prompt}
205:             rows={3}
206:             onChange={(event) => setPrompt(event.target.value)}
207:             placeholder="Describe the geometry or ask the helper for guidance…"
208:           />
209:         </label>
210:         <div className="chat-panel-actions">
211:           <button type="submit" className="chat-panel-send" disabled={!canSend}>
212:             {chat.inFlight ? 'Sending…' : 'Send'}
213:           </button>
214:           {chat.inFlight ? (
215:             <button type="button" className="chat-panel-cancel" onClick={onCancel}>
216:               Cancel
217:             </button>
218:           ) : null}
219:           {!configured && providerId ? (
220:             <span className="chat-panel-warning">
221:               Provider is not configured server-side.
222:             </span>
223:           ) : null}
224:         </div>
225:       </form>
226:     </section>
227:   );
228: }
229: 
230: function describeError(cause: unknown): { message: string; kind: 'cancelled' | 'timeout' | 'network' | 'server' } {
231:   if (cause instanceof StudioAbortError) return { message: 'cancelled', kind: 'cancelled' };
232:   if (cause instanceof StudioAuthError) return { message: `auth: ${cause.message} (${cause.status})`, kind: 'server' };
233:   if (cause instanceof StudioApiError) return { message: `${cause.code}: ${cause.message}`, kind: 'server' };
234:   if (cause instanceof StudioNetworkError) {
235:     if (cause.cause instanceof DOMException && cause.cause.name === 'AbortError') {
236:       return { message: 'cancelled', kind: 'cancelled' };
237:     }
238:     return { message: cause.message, kind: 'network' };
239:   }
240:   if (cause instanceof Error) return { message: cause.message, kind: 'network' };
241:   return { message: 'unknown error', kind: 'network' };
242: }

