230: function describeError(cause: unknown): { message: string; kind: 'cancelled' | 'timeout' | 'network' | 'server' } {
231:   if (cause instanceof StudioAbortError) return { message: 'cancelled', kind: 'cancelled' };
232:   if (cause instanceof StudioAuthError) return { message: `auth: ${cause.message} (${cause.status})`, kind: 'server' };
233:   if (cause instanceof StudioApiError) return { message: `${cause.code}: ${cause.message}`, kind: 'server' };
234:   if (cause instanceof StudioNetworkError) {
235:     if (cause.cause instanceof DOMException && cause.cause.name === 'AbortError') {
236:       return { message: 'cancelled', kind: 'cancelled' };
237:     }
238:     return { message: cause.message, kind: 'network' };
239:   }
240:   if (cause instanceof Error) return { message: cause.message, kind: 'network' };
241:   return { message: 'unknown error', kind: 'network' };
242: }

