152:   const p = props.parameters as SphereParameters;
153:   return (
154:     <div className="inspector-grid">
155:       <NumberField label="Radius" value={p.radius} min={0.1} max={2000} suffix="mm" onChange={(next) => patchSphere(p, { radius: next })} />
156:       <NumberField label="Rings" value={p.rings} min={3} max={96} integer step={1} onChange={(next) => patchSphere(p, { rings: clampInt(next, 3, 96) })} />
157:       <NumberField label="Sectors" value={p.sectors} min={4} max={128} integer step={1} onChange={(next) => patchSphere(p, { sectors: clampInt(next, 4, 128) })} />
158:     </div>
159:   );
160: }
161: 
162: interface BoundsReadoutProps {
163:   parameters: StudioParameters;
164:   bounds: { min: [number, number, number]; max: [number, number, number] };
165:   serverBounds: { min: [number, number, number]; max: [number, number, number] } | null;
166: }
167: 
168: function BoundsReadout(props: BoundsReadoutProps): ReactElement {
169:   const dims = boundsDimensions(props.bounds);
170:   const drift = props.serverBounds ? describeBoundsDrift(dims, boundsDimensions(props.serverBounds)) : [];
171:   return (
172:     <section className="inspector-bounds" aria-label="Computed bounds in millimetres">
173:       <h3>Bounds (mm)</h3>
174:       <dl>
175:         <div><dt>Width</dt><dd>{formatMillimetres(dims.width)}</dd></div>
176:         <div><dt>Height</dt><dd>{formatMillimetres(dims.height)}</dd></div>
177:         <div><dt>Depth</dt><dd>{formatMillimetres(dims.depth)}</dd></div>
178:       </dl>
179:       {drift.length > 0 ? (
180:         <p className="inspector-drift" role="status">
181:           Server-verified bounds differ from local preview by{' '}
182:           {drift.map((entry) => `${entry.label} ${entry.value}`).join(', ')}.
183:         </p>
184:       ) : null}
185:     </section>
186:   );
187: }
188: 
189: interface DriftEntry {
190:   label: string;
191:   value: string;
192: }
193: 
194: function describeBoundsDrift(
195:   local: { width: number; height: number; depth: number },
196:   server: { width: number; height: number; depth: number },
197: ): DriftEntry[] {
198:   const tolerance = 0.01;
199:   const items: DriftEntry[] = [];
200:   for (const [label, a, b] of [
201:     ['width', local.width, server.width],
202:     ['height', local.height, server.height],
203:     ['depth', local.depth, server.depth],
204:   ] as ReadonlyArray<[string, number, number]>) {
205:     const delta = Math.abs(a - b);
206:     if (delta > tolerance) items.push({ label, value: `${delta.toFixed(3)} mm` });
207:   }
208:   return items;
209: }
210: 
211: function patchBox(current: BoxParameters, patch: Partial<BoxParameters>): void {
212:   const next = { ...current, ...patch };
213:   const err = validateBox(next);
214:   if (err) {
215:     // Show local validation error rather than dispatching a partial change
216:     // that would also fail server-side.
217:     dispatch({ type: 'parameters/change', parameters: next });
218:     return;
219:   }
220:   dispatch({ type: 'parameters/change', parameters: next });
221: }
222: 
223: function patchCylinder(current: CylinderParameters, patch: Partial<CylinderParameters>): void {
224:   const next = { ...current, ...patch };
225:   validateCylinder(next);
226:   dispatch({ type: 'parameters/change', parameters: next });
227: }
228: 
229: function patchSphere(current: SphereParameters, patch: Partial<SphereParameters>): void {
230:   const next = { ...current, ...patch };
231:   validateSphere(next);
232:   dispatch({ type: 'parameters/change', parameters: next });
233: }
234: 
235: function clampInt(value: number, min: number, max: number): number {
236:   if (!Number.isFinite(value)) return min;
237:   const rounded = Math.round(value);
238:   if (rounded < min) return min;
239:   if (rounded > max) return max;
240:   return rounded;
241: }
242: 
243: // Re-export the local builders so other components can call them without
244: // reaching into the viewer module.
245: export const localPreviewFor = {
246:   box: (p: BoxParameters) => buildBox(p),
247:   cylinder: (p: CylinderParameters) => buildCylinder(p),
248:   sphere: (p: SphereParameters) => buildSphere(p),
249: };

