331: export function buildSphere(p: SphereParameters): StudioLocalPreview {
332:   const err = validateSphere(p);
333:   if (err) return emptyPreview('sphere', p);
334:   const rings = p.rings;
335:   const sectors = p.sectors;
336:   const positions: number[] = [];
337:   const normals: number[] = [];
338:   const indices: number[] = [];
339: 
340:   // Vertex layout: rings 0..rings inclusive. Ring 0 is the north pole, ring
341: // rings is the south pole, and the rings in between each have `sectors+1`
342: // longitude vertices. The poles share a single vertex index each so the
343: // fan triangles around them stay non-degenerate.
344: const northPoleIndex = 0;
345: positions.push(0, 0, p.radius);
346: normals.push(0, 0, 1);
347: 
348: for (let ringIdx = 1; ringIdx < rings; ringIdx++) {
349:     const phi = (Math.PI * ringIdx) / rings;
350:     const sinPhi = Math.sin(phi);
351:     const cosPhi = Math.cos(phi);
352:     for (let sec = 0; sec <= sectors; sec++) {
353:       const theta = (TWO_PI * sec) / sectors;
354:       const cosT = Math.cos(theta);
355:       const sinT = Math.sin(theta);
356:       const x = p.radius * sinPhi * cosT;
357:       const y = p.radius * sinPhi * sinT;
358:       const z = p.radius * cosPhi;
359:       positions.push(x, y, z);
360:       normals.push(x / p.radius, y / p.radius, z / p.radius);
361:     }
362: }
363: 
364: const southPoleIndex = positions.length / 3;
365: positions.push(0, 0, -p.radius);
366: normals.push(0, 0, -1);
367: 
368: // First non-pole ring starts at index 1; sector s of ring r is at
369: // `1 + (r - 1) * (sectors + 1) + s` for r in [1, rings-1].
370: for (let ringIdx = 0; ringIdx < rings; ringIdx++) {
371:     for (let sec = 0; sec < sectors; sec++) {
372:       if (ringIdx === 0) {
373:         // Top fan: north pole → ring1 sec → ring1 sec+1.
374:         const i0 = 1 + sec;
375:         const i1 = 1 + sec + 1;
376:         indices.push(northPoleIndex, i0, i1);
377:         continue;
378:       }
379:       if (ringIdx === rings - 1) {
380:         // Bottom fan: ringN sec+1 → ringN sec → south pole. The reverse
381:         // order keeps the geometric normal pointing -Z.
382:         const i0 = 1 + (ringIdx - 1) * (sectors + 1) + sec + 1;
383:         const i1 = 1 + (ringIdx - 1) * (sectors + 1) + sec;
384:         indices.push(southPoleIndex, i0, i1);
385:         continue;
386:       }
387:       const base = 1 + (ringIdx - 1) * (sectors + 1);
388:       const i0 = base + sec;
389:       const i1 = i0 + 1;
390:       const i2 = i0 + (sectors + 1);
391:       const i3 = i2 + 1;
392:       // CCW from outside: the geometric normal of (i0, i1, i2) is the
393:       // outward radial direction at that quad.
394:       indices.push(i0, i1, i2);
395:       indices.push(i1, i3, i2);
396:     }
397:   }
398: 
399:   return finishPreview('sphere', p, positions, normals, indices);
400: }
