142: export function validateParameters(kind: PrimitiveKind, p: StudioParameters): ValidationError | null {
143:   if (kind === 'box') return validateBox(p as BoxParameters);
144:   if (kind === 'cylinder') return validateCylinder(p as CylinderParameters);
145:   return validateSphere(p as SphereParameters);
