148: export function boundsFromPositions(positions: Float32Array): BBox {
149:   if (positions.length < 3) {
150:     return { min: [0, 0, 0], max: [0, 0, 0] };
151:   }
152:   let minX = positions[0]!;
153:   let minY = positions[1]!;
154:   let minZ = positions[2]!;
155:   let maxX = minX;
156:   let maxY = minY;
157:   let maxZ = minZ;
158:   for (let i = 3; i + 2 < positions.length; i += 3) {
159:     const x = positions[i]!;
160:     const y = positions[i + 1]!;
161:     const z = positions[i + 2]!;
162:     if (x < minX) minX = x; else if (x > maxX) maxX = x;
163:     if (y < minY) minY = y; else if (y > maxY) maxY = y;
164:     if (z < minZ) minZ = z; else if (z > maxZ) maxZ = z;
165:   }
166:   return { min: [minX, minY, minZ], max: [maxX, maxY, maxZ] };
167: }
168: 
169: function emptyPreview(kind: PrimitiveKind, p: StudioParameters): StudioLocalPreview {
170:   return {
171:     kind,
172:     parameters: p,
173:     positions: new Float32Array(0),
174:     normals: new Float32Array(0),
175:     indices: new Uint32Array(0),
176:     bounds: { min: [0, 0, 0], max: [0, 0, 0] },
177:     source: 'local',
178:     generatedAt: Date.now(),
179:     engine: LOCAL_ENGINE,
180:     warnings: ['parameters failed validation; no mesh emitted'],
181:   };
182: }
183: 
184: // --- Box -----------------------------------------------------------------
185: //
186: // Six flat-shaded faces. Each face is a regular subdivision grid that
187: // emits CCW triangles when viewed from outside (so the face normal
188: // agrees with the geometric triangle normal). The triangle winding
189: // `(i0, i1, i2)` and `(i1, i3, i2)` produces a geometric normal of
190: // `+u × +v`; we choose `u` and `v` so that direction matches the face
191: // outward direction.
192: 
193: export function buildBox(p: BoxParameters): StudioLocalPreview {
194:   const err = validateBox(p);
195:   if (err) return emptyPreview('box', p);
196:   const hx = p.size_x / 2;
197:   const hy = p.size_y / 2;
198:   const hz = p.size_z / 2;
199:   const n = p.subdivisions;
200: 
201:   type Face = { normal: readonly [number, number, number]; uAxis: 0 | 1 | 2; vAxis: 0 | 1 | 2; constant: 0 | 1 | 2; offset: number };
202:   // For each axis sign we pick `u`, `v` so that `+u × +v` equals the
203:   // outward direction. The axis order is a right-handed cycle, so we
204:   // pair each constant axis with the next two in (X, Y, Z) order, with
205:   // the order swapped when the outward sign is negative.
206:   const faces: readonly Face[] = [
207:     { normal: [1, 0, 0], uAxis: 1, vAxis: 2, constant: 0, offset: hx },
208:     { normal: [-1, 0, 0], uAxis: 2, vAxis: 1, constant: 0, offset: -hx },
209:     { normal: [0, 1, 0], uAxis: 2, vAxis: 0, constant: 1, offset: hy },
210:     { normal: [0, -1, 0], uAxis: 0, vAxis: 2, constant: 1, offset: -hy },
211:     { normal: [0, 0, 1], uAxis: 0, vAxis: 1, constant: 2, offset: hz },
212:     { normal: [0, 0, -1], uAxis: 1, vAxis: 0, constant: 2, offset: -hz },
213:   ];
214: 
215:   const halfExtents: readonly [number, number, number] = [hx, hy, hz];
216:   const positions: number[] = [];
217:   const normals: number[] = [];
218:   const indices: number[] = [];
219:   for (const face of faces) {
220:     const base = positions.length / 3;
221:     for (let row = 0; row <= n; row++) {
222:       const v = (row / n) * 2 - 1;
223:       for (let col = 0; col <= n; col++) {
224:         const u = (col / n) * 2 - 1;
225:         const coord: [number, number, number] = [0, 0, 0];
226:         coord[face.uAxis] = u * halfExtents[face.uAxis]!;
227:         coord[face.vAxis] = v * halfExtents[face.vAxis]!;
228:         coord[face.constant] = face.offset;
229:         positions.push(coord[0], coord[1], coord[2]);
230:         normals.push(face.normal[0], face.normal[1], face.normal[2]);
231:       }
232:     }
233:     for (let row = 0; row < n; row++) {
234:       for (let col = 0; col < n; col++) {
235:         const i0 = base + row * (n + 1) + col;
236:         const i1 = i0 + 1;
237:         const i2 = i0 + (n + 1);
238:         const i3 = i2 + 1;
239:         // Geometric normal of `(i0, i1, i2)` is `+u × +v`, which by the
240:         // face table equals the outward direction.
241:         indices.push(i0, i1, i2);
242:         indices.push(i1, i3, i2);
243:       }
244:     }
245:   }
246:   return finishPreview('box', p, positions, normals, indices);
247: }
248: 
249: // --- Cylinder ------------------------------------------------------------
250: //
251: // Side wall tessellated into radial_segments × height_segments quads with
252: // shared vertices giving smooth per-vertex normals; two end caps with their
253: // own pole-aligned normals. CCW when viewed from outside everywhere.
254: 
255: export function buildCylinder(p: CylinderParameters): StudioLocalPreview {
256:   const err = validateCylinder(p);
257:   if (err) return emptyPreview('cylinder', p);
258:   const radial = p.radial_segments;
259:   const rings = p.height_segments + 1;
260:   const halfH = p.height / 2;
261: 
262:   const positions: number[] = [];
263:   const normals: number[] = [];
264:   const indices: number[] = [];
265: 
266:   for (let ringIdx = 0; ringIdx < rings; ringIdx++) {
267:     const z = -halfH + (ringIdx / p.height_segments) * p.height;
268:     for (let seg = 0; seg <= radial; seg++) {
269:       const theta = (seg / radial) * TWO_PI;
270:       const cosT = Math.cos(theta);
271:       const sinT = Math.sin(theta);
272:       positions.push(p.radius * cosT, p.radius * sinT, z);
273:       normals.push(cosT, sinT, 0);
274:     }
275:   }
276:   for (let ringIdx = 0; ringIdx < p.height_segments; ringIdx++) {
277:     for (let seg = 0; seg < radial; seg++) {
278:       const i0 = ringIdx * (radial + 1) + seg;
279:       const i1 = i0 + 1;
280:       const i2 = i0 + (radial + 1);
281:       const i3 = i2 + 1;
282:       // CCW from outside the wall. Vertex grid is col-major over
283:       // (theta, z). With theta increasing first and z increasing second,
284:       // the geometric normal of (i0, i1, i2) is +theta × +z which points
285:       // radially outward at every quad.
286:       indices.push(i0, i1, i2);
287:       indices.push(i1, i3, i2);
288:     }
289:   }
290:   // Top cap: pole at +halfH.
291:   const topPole = positions.length / 3;
292:   positions.push(0, 0, halfH);
293:   normals.push(0, 0, 1);
294:   const topRingStart = positions.length / 3;
295:   for (let seg = 0; seg <= radial; seg++) {
296:     const theta = (seg / radial) * TWO_PI;
297:     const cosT = Math.cos(theta);
298:     const sinT = Math.sin(theta);
299:     positions.push(p.radius * cosT, p.radius * sinT, halfH);
300:     normals.push(0, 0, 1);
301:   }
302:   for (let seg = 0; seg < radial; seg++) {
303:     const i0 = topRingStart + seg;
304:     const i1 = i0 + 1;
305:     // CCW from above (+Z looking down at the cap): pole, then i0, then i1.
306:     indices.push(topPole, i0, i1);
307:   }
308:   // Bottom cap: pole at -halfH, winding reversed.
309:   const bottomPole = positions.length / 3;
310:   positions.push(0, 0, -halfH);
311:   normals.push(0, 0, -1);
312:   const bottomRingStart = positions.length / 3;
313:   for (let seg = 0; seg <= radial; seg++) {
314:     const theta = (seg / radial) * TWO_PI;
315:     const cosT = Math.cos(theta);
316:     const sinT = Math.sin(theta);
317:     positions.push(p.radius * cosT, p.radius * sinT, -halfH);
318:     normals.push(0, 0, -1);
319:   }
320:   for (let seg = 0; seg < radial; seg++) {
321:     const i0 = bottomRingStart + seg;
322:     const i1 = i0 + 1;
323:     indices.push(bottomPole, i1, i0);
324:   }
325: 
326:   return finishPreview('cylinder', p, positions, normals, indices);
327: }
328: 
329: // --- Sphere --------------------------------------------------------------
330: 
331: export function buildSphere(p: SphereParameters): StudioLocalPreview {
332:   const err = validateSphere(p);
333:   if (err) return emptyPreview('sphere', p);
334:   const rings = p.rings;
335:   const sectors = p.sectors;
336:   const positions: number[] = [];
337:   const normals: number[] = [];
338:   const indices: number[] = [];
339: 
340:   // Vertex layout: rings 0..rings inclusive. Ring 0 is the north pole, ring
341: // rings is the south pole, and the rings in between each have `sectors+1`
342: // longitude vertices. The poles share a single vertex index each so the
343: // fan triangles around them stay non-degenerate.
344: const northPoleIndex = 0;
345: positions.push(0, 0, p.radius);
346: normals.push(0, 0, 1);
347: 
348: for (let ringIdx = 1; ringIdx < rings; ringIdx++) {
349:     const phi = (Math.PI * ringIdx) / rings;
350:     const sinPhi = Math.sin(phi);
351:     const cosPhi = Math.cos(phi);
352:     for (let sec = 0; sec <= sectors; sec++) {
353:       const theta = (TWO_PI * sec) / sectors;
354:       const cosT = Math.cos(theta);
355:       const sinT = Math.sin(theta);
356:       const x = p.radius * sinPhi * cosT;
357:       const y = p.radius * sinPhi * sinT;
358:       const z = p.radius * cosPhi;
359:       positions.push(x, y, z);
360:       normals.push(x / p.radius, y / p.radius, z / p.radius);
361:     }
362: }
363: 
364: const southPoleIndex = positions.length / 3;
365: positions.push(0, 0, -p.radius);
366: normals.push(0, 0, -1);
367: 
368: // First non-pole ring starts at index 1; sector s of ring r is at
369: // `1 + (r - 1) * (sectors + 1) + s` for r in [1, rings-1].
370: for (let ringIdx = 0; ringIdx < rings; ringIdx++) {
371:     for (let sec = 0; sec < sectors; sec++) {
372:       if (ringIdx === 0) {
373:         // Top fan: north pole → ring1 sec → ring1 sec+1.
374:         const i0 = 1 + sec;
375:         const i1 = 1 + sec + 1;
376:         indices.push(northPoleIndex, i0, i1);
377:         continue;
378:       }
379:       if (ringIdx === rings - 1) {
380:         // Bottom fan: ringN sec+1 → ringN sec → south pole. The reverse
381:         // order keeps the geometric normal pointing -Z.
382:         const i0 = 1 + (ringIdx - 1) * (sectors + 1) + sec + 1;
383:         const i1 = 1 + (ringIdx - 1) * (sectors + 1) + sec;
384:         indices.push(southPoleIndex, i0, i1);
385:         continue;
386:       }
387:       const base = 1 + (ringIdx - 1) * (sectors + 1);
388:       const i0 = base + sec;
389:       const i1 = i0 + 1;
390:       const i2 = i0 + (sectors + 1);
391:       const i3 = i2 + 1;
392:       // CCW from outside: the geometric normal of (i0, i1, i2) is the
393:       // outward radial direction at that quad.
394:       indices.push(i0, i1, i2);
395:       indices.push(i1, i3, i2);
396:     }
397:   }
398: 
399:   return finishPreview('sphere', p, positions, normals, indices);
400: }
401: 
402: function finishPreview(
403:   kind: PrimitiveKind,
404:   p: StudioParameters,
405:   positions: ReadonlyArray<number>,
406:   normals: ReadonlyArray<number>,
407:   indices: ReadonlyArray<number>,
408: ): StudioLocalPreview {
409:   if (positions.length / 3 > MAX_MESH_VERTICES) {
410:     return emptyPreview(kind, p);
411:   }
412:   const positionsF32 = new Float32Array(positions);
413:   const normalsF32 = new Float32Array(normals);
414:   const indicesU32 = new Uint32Array(indices);
415:   return {
416:     kind,
417:     parameters: p,
418:     positions: positionsF32,
419:     normals: normalsF32,
420:     indices: indicesU32,
421:     bounds: boundsFromPositions(positionsF32),
422:     source: 'local',
423:     generatedAt: Date.now(),
424:     engine: LOCAL_ENGINE,
425:     warnings: [],
426:   };
427: }
428: 
429: export function buildLocal(kind: PrimitiveKind, p: StudioParameters): StudioLocalPreview {
430:   if (kind === 'box') return buildBox(p as BoxParameters);
431:   if (kind === 'cylinder') return buildCylinder(p as CylinderParameters);
432:   return buildSphere(p as SphereParameters);
433: }
434: 
435: export function boundsDimensions(b: BBox): { width: number; height: number; depth: number } {
436:   return {
437:     width: b.max[0] - b.min[0],
438:     height: b.max[1] - b.min[1],
439:     depth: b.max[2] - b.min[2],
440:   };
441: }
442: 
443: export function formatMillimetres(value: number): string {
444:   if (!Number.isFinite(value)) return '—';
445:   return `${value.toFixed(2)} mm`;
446: }

