205:     });
206:   }
207: 
208:   function disposeMeshGroup(): void {
209:     if (meshGroup.current) {
210:       scene.remove(meshGroup.current);
211:       disposeObject(meshGroup.current);
212:       meshGroup.current = null;
213:     }
214:   }
215: 
216:   function disposeHelpers(): void {
217:     grid.geometry.dispose();
218:     const gridMat = grid.material as THREE.Material | THREE.Material[];
219:     if (Array.isArray(gridMat)) gridMat.forEach((m) => m.dispose());
220:     else gridMat.dispose();
221:     axes.geometry.dispose();
222:     const axesMat = axes.material as THREE.LineBasicMaterial;
223:     axesMat.dispose();
224:   }
225: 
226:   function applyMesh(
227:     mesh: StudioLocalPreview | PreviewResponse | null,
228:     source: 'local' | 'server' | 'none',
229:   ): void {
230:     if (!mesh) {
231:       disposeMeshGroup();
232:       clearDimensions();
233:       currentBounds = null;
234:       renderNow();
235:       return;
236:     }
237:     const geometry = meshToGeometry(mesh);
238:     if (!geometry) {
239:       disposeMeshGroup();
240:       clearDimensions();
241:       currentBounds = null;
242:       renderNow();
243:       return;
244:     }
245:     disposeMeshGroup();
246:     const group = new THREE.Group();
247:     const threeMesh = new THREE.Mesh(geometry, makeMaterial(viewport.material));
248:     group.add(threeMesh);
249:     scene.add(group);
250:     meshGroup.current = group;
251:     currentBounds = mesh.bounds;
252:     frameOnBounds(mesh.bounds, source === 'none' ? 'server' : source);
253:     renderDimensions(mesh.bounds);
254:     renderNow();
255:   }
256: 
257:   function frameOnBounds(bounds: BBox, source: 'local' | 'server' | 'none'): void {
258:     const min = new THREE.Vector3(bounds.min[0], bounds.min[1], bounds.min[2]);
259:     const max = new THREE.Vector3(bounds.max[0], bounds.max[1], bounds.max[2]);
260:     const centre = min.clone().add(max).multiplyScalar(0.5);
261:     const size = max.clone().sub(min);
262:     const radius = Math.max(size.x, size.y, size.z, 1);
263:     const distance = radius * 3.2;
264:     if (source === 'none') return;
265:     controls.target.copy(centre);
266:     camera.position.copy(centre.clone().add(new THREE.Vector3(distance, distance * 0.75, distance)));
267:     controls.update();
268:   }
269: 
270:   function applyViewport(next: ViewportSnapshot): void {
271:     const materialChanged = next.material !== viewport.material;
272:     viewport = next;
273:     grid.visible = next.showGrid;
274:     axes.visible = next.showAxes;
275:     scene.background = new THREE.Color(BACKGROUND_COLORS[next.background]);
276:     if (dimensionOverlay.current) {
277:       dimensionOverlay.current.element.style.display = next.showDimensions ? '' : 'none';
278:     }
279:     if (meshGroup.current && materialChanged) {
280:       const child = meshGroup.current.children[0];
281:       if (child instanceof THREE.Mesh) {
282:         // Dispose the previous material so we don't leak GPU resources on
283:         // every material-kind toggle.
284:         const old = child.material;
285:         child.material = makeMaterial(next.material);
286:         if (Array.isArray(old)) old.forEach((m) => m.dispose());
287:         else old.dispose();
288:       }
289:     }
290:     renderNow();
291:   }
292: 
293:   function renderDimensions(bounds: BBox): void {
294:     clearDimensions();
295:     if (!viewport.showDimensions) return;
296:     const dims = boundsDimensions(bounds);
297:     const element = document.createElement('div');
298:     element.className = 'viewer-canvas-dimensions';
299:     element.setAttribute('role', 'status');
300:     element.textContent = [
301:       `Width  ${formatMillimetres(dims.width)}`,
302:       `Height ${formatMillimetres(dims.height)}`,
303:       `Depth  ${formatMillimetres(dims.depth)}`,
304:     ].join('   ');
305:     overlayHost.appendChild(element);
306:     dimensionOverlay.current = { element };
307:   }
308: 
309:   function clearDimensions(): void {
310:     if (dimensionOverlay.current) {
311:       dimensionOverlay.current.element.remove();
312:       dimensionOverlay.current = null;
313:     }
314:   }
315: 
316:   function makeMaterial(kind: MaterialKind): THREE.Material {
317:     if (kind === 'wireframe') return new THREE.MeshBasicMaterial({ color: 0x66ccff, wireframe: true });
318:     if (kind === 'matte') {
319:       return new THREE.MeshStandardMaterial({ color: 0xb4c4d6, metalness: 0.0, roughness: 0.95 });
320:     }
321:     return new THREE.MeshStandardMaterial({ color: 0x7aa6ff, metalness: 0.15, roughness: 0.45 });
322:   }
323: 
324:   function handleResize(): void {
325:     const rect = container.getBoundingClientRect();
326:     const w = Math.max(1, rect.width);
327:     const h = Math.max(1, rect.height);
328:     camera.aspect = w / h;
329:     camera.updateProjectionMatrix();
330:     renderer.setSize(w, h, false);
331:   }
332: 
333:   return {
334:     applyMesh,
335:     applyViewport,
336:     renderNow,
337:     handleResize,
338:     dispose(): void {
339:       disposed = true;
340:       controls.removeEventListener('change', renderNow);
341:       clearDimensions();
342:       disposeMeshGroup();
343:       disposeHelpers();
344:       renderer.dispose();
345:       controls.dispose();
346:       if (renderer.domElement.parentNode === container) {
347:         container.removeChild(renderer.domElement);
348:       }
349:       scene.traverse((object) => {
350:         if (object instanceof THREE.Mesh) {
351:           object.geometry.dispose();
352:           const m = object.material;
353:           if (Array.isArray(m)) m.forEach((mm) => mm.dispose());
354:           else m.dispose();
355:         }
356:       });
357:       currentBounds = null;
358:     },
359:   };
360: }
361: 
362: function meshToGeometry(mesh: StudioLocalPreview | PreviewResponse): THREE.BufferGeometry | null {
363:   const positions = mesh.positions instanceof Float32Array
364:     ? mesh.positions
365:     : new Float32Array(mesh.positions);
366:   const normals = mesh.normals instanceof Float32Array
367:     ? mesh.normals
368:     : new Float32Array(mesh.normals);
369:   const indices = mesh.indices instanceof Uint32Array
370:     ? mesh.indices
371:     : new Uint32Array(mesh.indices);
372:   if (positions.length < 9 || indices.length < 3) return null;
373:   const geometry = new THREE.BufferGeometry();
374:   geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
375:   if (normals.length === positions.length) {
376:     geometry.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
377:   } else {
378:     geometry.computeVertexNormals();
379:   }
380:   geometry.setIndex(new THREE.BufferAttribute(indices, 1));
381:   geometry.computeBoundingSphere();
382:   return geometry;
383: }
