385: function renderWebGLFallback(container: HTMLDivElement, cause: unknown): void {
386:   const message = document.createElement('div');
387:   message.className = 'viewer-canvas-fallback';
388:   message.setAttribute('role', 'status');
389:   const reason = cause instanceof Error ? cause.message : 'WebGL is not available in this context.';
390:   message.textContent = `3D preview unavailable: ${reason}. The inspector and panels still work.`;
391:   container.appendChild(message);
392: }

