1: /* Kala Studio — single bundled stylesheet.
2:  *
3:  * The whole UI is a CSS grid of:
4:  *   header · sidebar · viewport · inspector · chat · footer.
5:  * No external font, no CDN, no remote assets. Every text colour and
6:  * background here is paired with a non-colour indicator (icon or text) so
7:  * the UI does not rely on colour alone to convey state.
8:  */
9: 
10: :root {
11:   --bg-0: #0c1116;
12:   --bg-1: #14181f;
13:   --bg-2: #1a2029;
14:   --bg-3: #232a35;
15:   --bg-elev: #2a3340;
16:   --fg-0: #e6ecf3;
17:   --fg-1: #c5cfdb;
18:   --fg-2: #8b97a7;
19:   --fg-3: #5a6675;
20:   --accent: #66ccff;
21:   --accent-strong: #2a99ff;
22:   --warning: #f0a830;
23:   --danger: #ff6b6b;
24:   --success: #5fd07a;
25:   --grid-line: #2a323d;
26:   --border: #2e3744;
27:   --shadow: 0 6px 24px rgba(0, 0, 0, 0.45);
28:   --radius: 6px;
29:   --gap: 12px;
30:   --gap-lg: 16px;
31: }
32: 
33: * {
34:   box-sizing: border-box;
35: }
36: 
37: html, body, #root {
38:   margin: 0;
39:   padding: 0;
40:   height: 100%;
41:   /* The app shell owns all scrolling: each region scrolls internally.
42:    * Without this the document itself scrolls and an over-tall column
43:    * (e.g. the sidebar) exposes a page scrollbar and pushes the footer
44:    * off-screen. */
45:   overflow: hidden;
46:   background: var(--bg-0);
47:   color: var(--fg-0);
48:   font: 14px/1.45 -apple-system, "Segoe UI", "Cantarell", "Ubuntu", system-ui, sans-serif;
49:   font-feature-settings: "tnum" 1, "cv02" 1;
50:   text-rendering: optimizeLegibility;
51:   -webkit-font-smoothing: antialiased;
52: }
53: 
54: button {
55:   font: inherit;
56:   color: inherit;
57:   background: transparent;
58:   border: 1px solid transparent;
59:   cursor: pointer;
60: }
61: 
62: button:disabled {
63:   cursor: not-allowed;
64:   opacity: 0.55;
65: }
66: 
67: input, select, textarea {
68:   font: inherit;
69:   color: var(--fg-0);
70:   background: var(--bg-2);
71:   border: 1px solid var(--border);
72:   border-radius: var(--radius);
73:   padding: 6px 8px;
74: }
75: 
76: input:focus, select:focus, textarea:focus, button:focus-visible {
77:   outline: 2px solid var(--accent);
78:   outline-offset: 1px;
79: }
80: 
81: code {
82:   font: 12px/1.5 ui-monospace, "JetBrains Mono", "Cascadia Mono", "SF Mono", monospace;
83:   background: var(--bg-2);
84:   padding: 1px 4px;
85:   border-radius: 4px;
86: }
87: 
88: /* App shell ----------------------------------------------------------- */
89: 
90: .app-shell {
91:   display: grid;
92:   grid-template-rows: auto minmax(0, 1fr) auto;
93:   grid-template-columns: minmax(0, 1fr);
94:   height: 100%;
95:   background: var(--bg-0);
96: }
97: 
98: .app-shell-body {
99:   display: grid;
100:   grid-template-columns: 220px minmax(0, 1fr);
101:   /* Bound the single row. Without an explicit row the implicit `auto`
102:    * track sized itself to the tallest column (the sidebar's intrinsic
103:    * content), so the row grew past the shell and pushed the viewport,
104:    * canvas and footer out of the window. `minmax(0, 1fr)` pins it to the
105:    * shell height; the sidebar then scrolls internally. */
106:   grid-template-rows: minmax(0, 1fr);
107:   min-height: 0;
108:   min-width: 0;
109:   overflow: hidden;
110: }
