1020: /* Compact screens ----------------------------------------------------- */
1021: 
1022: @media (max-width: 1100px) {
1023:   /* Stack toolbar / viewport / rail and BOUND both content rows so a
1024:    * short, narrow window (e.g. 960x720) stays usable: the viewport and
1025:    * the rail each scroll internally instead of growing the main column
1026:    * past the shell and pushing the footer off-screen. */
1027:   .app-shell-main {
1028:     grid-template-columns: minmax(0, 1fr);
1029:     grid-template-rows: auto minmax(0, 1.4fr) minmax(0, 1fr);
1030:     grid-template-areas:
1031:       "toolbar"
1032:       "viewport"
1033:       "rail";
1034:   }
1035: }
1036: 
