32:   const cx = positions[c * 3] ?? 0;
33:   const cy = positions[c * 3 + 1] ?? 0;
34:   const cz = positions[c * 3 + 2] ?? 0;
35:   const ux = bx - ax;
36:   const uy = by - ay;
37:   const uz = bz - az;
38:   const vx = cx - ax;
39:   const vy = cy - ay;
40:   const vz = cz - az;
