25: function triArea(positions: Float32Array, a: number, b: number, c: number): number {
26:   const ax = positions[a * 3] ?? 0;
27:   const ay = positions[a * 3 + 1] ?? 0;
28:   const az = positions[a * 3 + 2] ?? 0;
29:   const bx = positions[b * 3] ?? 0;
30:   const by = positions[b * 3 + 1] ?? 0;
31:   const bz = positions[b * 3 + 2] ?? 0;
32:   const cx = positions[c * 3] ?? 0;
33:   const cy = positions[c * 3 + 1] ?? 0;
34:   const cz = positions[c * 3 + 2] ?? 0;
35:   const ux = bx - ax;
36:   const uy = by - ay;
37:   const uz = bz - az;
38:   const vx = cx - ax;
39:   const vy = cy - ay;
40:   const vz = cz - az;
41:   const nx = uy * vz - uz * vy;
42:   const ny = uz * vx - ux * vz;
43:   const nz = ux * vy - uy * vx;
44:   return 0.5 * Math.sqrt(nx * nx + ny * ny + nz * nz);
45: }
