47: function winding(positions: Float32Array, indices: Uint32Array): number {
48:   let inward = 0;
49:   let outward = 0;
50:   for (let i = 0; i + 2 < indices.length; i += 3) {
51:     const a = indices[i]!;
52:     const b = indices[i + 1]!;
53:     const c = indices[i + 2]!;
54:     const ax = positions[a * 3] ?? 0;
55:     const ay = positions[a * 3 + 1] ?? 0;
56:     const az = positions[a * 3 + 2] ?? 0;
57:     const bx = positions[b * 3] ?? 0;
58:     const by = positions[b * 3 + 1] ?? 0;
59:     const bz = positions[b * 3 + 2] ?? 0;
60:     const cx = positions[c * 3] ?? 0;
61:     const cy = positions[c * 3 + 1] ?? 0;
62:     const cz = positions[c * 3 + 2] ?? 0;
63:     const ux = bx - ax, uy = by - ay, uz = bz - az;
64:     const vx = cx - ax, vy = cy - ay, vz = cz - az;
65:     const nx = uy * vz - uz * vy;
66:     const ny = uz * vx - ux * vz;
67:     const nz = ux * vy - uy * vx;
68:     const dot =
69:       (ax + bx + cx) * nx +
70:       (ay + by + cy) * ny +
71:       (az + bz + cz) * nz;
72:     if (dot > 0) outward++;
73:     else if (dot < 0) inward++;
74:   }
75:   const total = inward + outward;
76:   return total > 0 ? outward / total : 1;
77: }
