input.newString:
.chat-panel {
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  display: grid;
  /* header · intro (context + starters) · scrolling thread · composer */
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  min-height: 0;
}

.chat-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border);
}

.chat-panel-heading {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.chat-panel-subtitle {
  margin: 0;
  font-size: 12px;
  color: var(--fg-2);
}

.chat-panel-intro {
  display: grid;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-2);
  overflow: auto;
  max-height: 34vh;
}

/* Active Geometry Context — the OpenCascade primitive the agent is sizing. */
.chat-panel-context {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 10px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-1);
  font-size: 12px;
  color: var(--fg-1);
}

.chat-panel-context-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--fg-2);
}

.chat-panel-context-kind {
  color: var(--accent);
  text-transform: uppercase;
}

.chat-panel-context-dims {
  font-family: ui-monospace, monospace;
  color: var(--fg-0);
}

.chat-panel-context-envelope,
.chat-panel-context-volume {
  font-family: ui-monospace, monospace;
  color: var(--fg-2);
}

.chat-panel-starters {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chat-panel-starter {
  padding: 5px 10px;
  border: 1px dashed var(--border);
  border-radius: 999px;
  background: var(--bg-1);
  color: var(--fg-1);
  font-size: 12px;
}

.chat-panel-starter:hover {
  background: var(--bg-3);
  color: var(--fg-0);
}

