210:     setPhase({ kind: 'error', message });
211:     dispatch({ type: 'connection/error', message });
212:     return;
213:   }
214:   dispatch({ type: 'connection/ready', connection });
215:   setPhase({ kind: 'connecting', message: 'Loading registries…' });
216:   void loadRegistries(handle, connection, setPhase);
217: }
218: 
219: async function loadRegistries(
220:   handle: RegistryHandle,
221:   connection: StudioConnection,
222:   setPhase: (next: Phase) => void,
223: ): Promise<void> {
224:   // Claim this handle for the new load. Any earlier load's callbacks now
225:   // fail the identity check and bail.
226:   const loadId: object = {};
227:   handle.activeLoad = loadId;
228:   const healthController = new AbortController();
229:   const integrationsController = new AbortController();
230:   const providersController = new AbortController();
231:   handle.controllers.push(healthController, integrationsController, providersController);
232: 
233:   const timers: ReturnType<typeof setTimeout>[] = [];
234:   const timeout = (controller: AbortController, ms: number) => {
235:     const timer = setTimeout(() => controller.abort(), ms);
236:     timers.push(timer);
237:   };
238:   timeout(healthController, 5_000);
239:   timeout(integrationsController, 5_000);
240:   timeout(providersController, 5_000);
241: 
242:   const superseded = () => !handle.alive || handle.activeLoad !== loadId;
243: 
244:   try {
245:     const [health, integrations, providers] = await Promise.all([
246:       getHealth(connection, healthController.signal),
247:       getIntegrations(connection, integrationsController.signal),
248:       getProviders(connection, providersController.signal),
249:     ]);
250:     if (superseded()) return;
251:     dispatch({
252:       type: 'server/providers',
253:       providers: providers.providers,
254:       health: 'ok',
255:       healthMessage: health.status,
256:       version: health.version,
257:       stepAvailable: health.step_available,
258:     });
259:     dispatch({ type: 'server/integrations', integrations: integrations.integrations });
260:   } catch (cause) {
261:     if (superseded()) return;
262:     const message = describeError(cause);
263:     dispatch({
264:       type: 'server/providers',
265:       providers: [],
266:       health: 'unreachable',
267:       healthMessage: message,
268:       version: '',
269:       stepAvailable: false,
270:     });
271:     setPhase({ kind: 'error', message });
272:   } finally {
273:     for (const timer of timers) clearTimeout(timer);
274:     handle.controllers = handle.controllers.filter(
275:       (c) => c !== healthController && c !== integrationsController && c !== providersController,
276:     );
277:   }
278: }
279: 
280: function isMissingBridgeError(cause: unknown): boolean {
281:   return cause instanceof Error && cause.message.includes('desktop bridge unavailable');
282: }
283: 
284: function describeError(cause: unknown): string {
285:   if (cause instanceof StudioApiError) return `${cause.code}: ${cause.message}`;
286:   if (cause instanceof StudioNetworkError) return cause.message;
287:   if (cause instanceof Error) return cause.message;
288:   return 'unknown error';
289: }

